using WICareerBuilder.Data.Database;using WICareerBuilder.Data.Repositories;
namespace WICareerBuilder.Data.Tests;
[TestClass]
public sealed class CareerCvRepositoryTests
{
 [TestMethod] public async Task Migration0024_AdvancesFormatVersion(){await WithRepositoryAsync(async(db,_)=>{await using var c=await db.OpenConnectionAsync();var q=c.CreateCommand();q.CommandText="SELECT setting_value FROM settings WHERE setting_key='data_format_version';";var versionValue=Convert.ToString(await q.ExecuteScalarAsync());Assert.IsTrue(int.TryParse(versionValue,out var dataFormatVersion)&&dataFormatVersion>=24,$"Migration 0024 requires data format version >= 24; actual value was {versionValue ?? "<null>"}.");});}
 [TestMethod] public async Task MultipleCvs_DrawFromMasterEvidenceButRequireApproval(){await WithRepositoryAsync(async(_,r)=>{var ev=await r.CreateCareerEvidenceAsync("Bench proof","ProjectTest","DemonstratedProject","Tested",null,null,true,true,"Reviewed","Private",true);var eng=await r.CreateCareerCvAsync("Engineering CV","Electronics Engineer","Engineering");var sw=await r.CreateCareerCvAsync("Software CV","Software Engineer","Software");await Assert.ThrowsExactlyAsync<InvalidOperationException>(()=>r.AddEvidenceToCvAsync(eng,ev,"Project","Built and tested system"));var summary=await r.GetMasterEvidenceSummaryAsync();Assert.AreEqual(2,summary.CvCount);Assert.AreEqual(1,summary.EvidenceCount);Assert.AreEqual(0,summary.ApprovedCvEvidenceCount);Assert.AreEqual(0,(await r.GetCareerCvItemsAsync(sw)).Count);});}

 [TestMethod] public async Task ConfirmedHeldCredential_CanBeAddedToCareerSpecificCv(){await WithRepositoryAsync(async(_,r)=>{var credential=await r.CreateCareerCredentialAsync("Qualification","Engineering Award","External College","Held","","","UserConfirmed",true,null,"");var cv=await r.CreateCareerCvAsync("Engineering evidence CV","Engineer","Engineering");await r.AddCredentialToCvAsync(cv,credential,"Qualifications","Engineering Award — External College");Assert.AreEqual(1,(await r.GetCareerCvItemsAsync(cv)).Count);});}
 private static async Task WithRepositoryAsync(Func<DatabaseService,LibraryRepository,Task> body){var root=Path.Combine(Path.GetTempPath(),"WICareerBuilder.Tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var db=new DatabaseService(Path.Combine(root,"careerbuilder.db"));await db.InitializeAsync();await body(db,new LibraryRepository(db));}finally{try{Directory.Delete(root,true);}catch{}}}
}
